const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Chongqing geometry (central urban area)
  const chongqing = ee.Geometry.Point([106.552, 29.563]).buffer(20000); // 20km buffer around city center

  // 2. Define time periods
  const period1_start = '2020-02-10';
  const period1_end = '2020-02-25';
  const period2_start = '2020-04-20';
  const period2_end = '2020-05-12';

  // 3. Function to get and process NO2 data
  async function getNO2Mean(startDate, endDate, periodName) {
    let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .select('NO2_column_number_density')
      .filterDate(startDate, endDate)
      .filterBounds(chongqing);

    const count = collection.size().getInfo();
    console.log(`${periodName} Images: ${count}`);

    if (count === 0) {
      return {mean: null, pixelCount: 0, valid: false};
    }

    // Create mean composite
    const meanImage = collection.mean();

    // Get pixel count and mean value
    const stats = meanImage.reduceRegion({
      reducer: ee.Reducer.count().combine({
        reducer2: ee.Reducer.mean(),
        sharedInputs: true
      }),
      geometry: chongqing,
      scale: 1000,
      maxPixels: 1e9
    });

    const pixelCount = ee.Number(stats.get('NO2_column_number_density_count')).getInfo();
    const meanValue = ee.Number(stats.get('NO2_column_number_density_mean')).getInfo();

    return {
      mean: meanValue,
      pixelCount: pixelCount,
      valid: (meanValue !== null && pixelCount > 0)
    };
  }

  // 4. Get data for both periods
  const period1 = await getNO2Mean(period1_start, period1_end, "Feb 10-25, 2020");
  const period2 = await getNO2Mean(period2_start, period2_end, "Apr 20-May 12, 2020");

  // 5. Check for missing data (C1)
  if (!period1.valid && period1.pixelCount === 0) {
    console.log("No valid data for Period 1");
    console.log("<answer>C1</answer>");
    return;
  }

  if (!period2.valid && period2.pixelCount === 0) {
    console.log("No valid data for Period 2");
    console.log("<answer>C1</answer>");
    return;
  }

  // 6. Check for no valid pixels (C2)
  if (period1.pixelCount === 0) {
    console.log("No valid pixels for Period 1 after processing");
    console.log("<answer>C2</answer>");
    return;
  }

  if (period2.pixelCount === 0) {
    console.log("No valid pixels for Period 2 after processing");
    console.log("<answer>C2</answer>");
    return;
  }

  console.log(`Period 1 (Feb): Mean NO2 = ${period1.mean?.toExponential(2)} mol/m², Pixels = ${period1.pixelCount}`);
  console.log(`Period 2 (Apr-May): Mean NO2 = ${period2.mean?.toExponential(2)} mol/m², Pixels = ${period2.pixelCount}`);

  // 7. Validate results (C3)
  if (period1.mean === null || period2.mean === null || 
      isNaN(period1.mean) || isNaN(period2.mean) ||
      period1.mean < 0 || period2.mean < 0) {
    console.log("Invalid calculation results");
    console.log("<answer>C3</answer>");
    return;
  }

  // 8. Compare values and determine answer
  const percentChange = ((period2.mean - period1.mean) / period1.mean) * 100;
  console.log(`Change: ${percentChange.toFixed(1)}%`);

  if (period2.mean > period1.mean) {
    console.log("<answer>A</answer>"); // Yes, NO2 increased
  } else {
    console.log("<answer>B</answer>"); // No, NO2 did not increase
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
